INSERT INTO ExamAttempt VALUES('2f1abf8d-ca3b-41b7-98e3-8999ef41a550','bc101141-005a-4dcb-bb03-35e811015338','af46d95d-2638-4af3-9049-b93409487353',1788453834940,1788453949839,1,0.0);
INSERT INTO Question VALUES('258770a7-6e5e-45f3-b8df-5673af2c14a3','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix',unistr('You plan to create the Power BI model shown in the exhibit. The data has the following refresh requirements:\u000a- Customer must be refreshed daily.\u000a- Date must be refreshed once every three years.\u000a- Sales must be refreshed in near real time.\u000a- SalesAggregate must be refreshed once per week.\u000a\u000aYou need to select the storage modes for the tables. The solution must meet the following requirements:\u000a- Minimize the load times of visuals.\u000a- Ensure that the data is loaded to the model based on the refresh requirements.\u000a\u000aWhich storage mode should you select for each table?'),'Customer and Date should use Dual mode to optimize performance for both DirectQuery (Sales) and Import (SalesAggregate) queries. Sales must be DirectQuery for near real-time updates. SalesAggregate should be Import to optimize weekly aggregation performance.',1,NULL,NULL,'{"rows":["Customer","Date","Sales","SalesAggregate"],"correct_mapping":{"0":"Dual","1":"Dual","2":"DirectQuery","3":"Import"}}',1788452319394);
INSERT INTO Question VALUES('e61bf8ba-ead6-489f-8048-7e9c8ffa1032','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice',unistr('You have a project management app that is fully hosted in Microsoft Teams. The app was developed by using Microsoft Power Apps.\u000aYou need to create a Power BI report that connects to the project management app.\u000aWhich connector should you select?'),'When using Power Apps in Microsoft Teams, the underlying data store is Microsoft Dataverse, so the Dataverse connector should be used.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('3e68993b-f122-445f-80e5-bc812ac6bf90','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice',unistr('For the sales department at your company, you publish a Power BI report that imports data from a Microsoft Excel file located in a Microsoft SharePoint folder. The data model contains several measures.\u000aYou need to create a Power BI report from the existing data. The solution must minimize development effort.\u000aWhich type of data source should you use?'),'Connecting to the existing Power BI dataset allows you to reuse the model and all existing measures, minimizing development effort.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('30c0f2c7-a49e-470f-a7fe-57f211b78db8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You import two Microsoft Excel tables named Customer and Address into Power Query. Customer contains Customer ID, Customer Name, Phone, Email Address, Address ID. Address contains Address ID, Address Line 1, Address Line 2, City, State/Region, Country, Postal Code. Each Customer ID represents a unique customer. Each Address ID represents a unique address. You need to create a query that has one row per customer containing City, State/Region, and Country. What should you do?','Merging queries performs a relational join on matching keys (Address ID) to extend columns horizontally, preserving one row per customer.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('625dcc20-23a7-4638-b955-c6bc8798d574','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You have two Azure SQL databases that contain the same tables and columns. For each database, you create a query that retrieves data from a table named Customer. You need to combine the Customer tables into a single table. The solution must minimize the size of the data model and support scheduled refresh in powerbi.com. What should you do?','Appending queries as new creates a consolidated table from identical structures. Disabling load on the initial queries prevents duplicate storage in memory while maintaining refresh pipelines.',1,NULL,NULL,'{"rows":["Option to use to combine the Customer tables","Action to perform on the original two SQL database queries"],"correct_mapping":{"0":"Append Queries as New","1":"Disable loading the query to the data model"}}',1788452319394);
INSERT INTO Question VALUES('acae6ad0-b04b-4cad-9a65-f23529713bee','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','In Power Query Editor, you have three queries named Product Category, ProductSubCategory, and Product. Every Product has a ProductSubCategory. Not every ProductSubCategory has a parent Product Category. You need to merge the three queries into a single query with optimal performance. Select the appropriate join kinds.','Product to ProductSubCategory requires an Inner join as every product matches. ProductSubCategory to ProductCategory requires a Left Outer join to retain subcategories without parent categories.',1,NULL,NULL,'{"dropZones":["Product | ProductSubCategory","ProductSubCategory | ProductCategory"],"correct_mapping":{"0":"Inner","1":"Left outer"}}',1788452319394);
INSERT INTO Question VALUES('173963a5-4b45-4a82-89a9-1eb26ebb673a','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You are building a Power BI report that uses data from an Azure SQL database named erp1. You import Products, Orders, and Order Line Items tables. You need to perform order metrics and product sales attribute analysis while minimizing visual update times. What should you do first?','Merging header (Orders) and line items (Order Line Items) flattens transaction header data into line details to establish an optimized Star Schema fact table.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('35589de1-0e2b-4388-adf0-5085905adf01','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You need to use Power BI Desktop to load only the manufacturing reports from a specific SharePoint document library folder. What should you do?','Using the SharePoint folder connector and selecting Transform allows filtering by Folder Path to restrict files exclusively to the target manufacturing reports library.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('3e4b8f47-fb54-44e3-8606-a39d1920c492','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','Combine products from Table1 and Table2 into a single query containing one column with no duplicate values. Which three actions should you perform in sequence?','First import data from Excel selecting both tables, then append Table2 to Table1 to combine all rows, and finally remove duplicate entries in Table1.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"From Power BI Desktop, import the data from Excel, and select Table1 and Table2.","1":"From Power Query Editor, append Table2 to Table1.","2":"From Power Query Editor, select Table1, and then select Remove duplicates."}}',1788452319394);
INSERT INTO Question VALUES('2f6841d8-7143-4ea5-8a20-bacaafc288c0','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have a CSV file with a Logged column formatted as ''2018-12-31 at 08:59''. You need to analyze complaints by logged date using a built-in date hierarchy. What should you do?','Splitting the column by ''at'' separates the date string from the time string, allowing conversion of the date part into a standard Date type.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('3406d1f4-6265-4ba5-a089-a39bd15301a1','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','You have a Microsoft Excel file in a Microsoft OneDrive folder. The file must be imported to a Power BI dataset. You need to ensure that the dataset can be refreshed in powerbi.com. Which two connectors can you use to connect to the file? Each correct answer presents a complete solution.','Web and SharePoint folder connectors allow direct URL/cloud-based paths to OneDrive files, enabling scheduled refreshes without needing an on-premises gateway.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('f7283623-ac67-41e0-859a-037e0c9c3590','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You are profiling data by using Power Query Editor. You have a table named Reports that contains a column named State. The distribution and quality data metrics for the data in State show 69 distinct and 4 unique values. Complete the statements.','Distinct values represent the total count of different values present (69). Unique values represent the count of values that occur exactly once (4).',1,NULL,NULL,'{"rows":["There are [answer choice] different values in State including nulls.","There are [answer choice] non-null values that occur only once in State."],"correct_mapping":{"0":"69","1":"4"}}',1788452319394);
INSERT INTO Question VALUES('21f194bd-4212-44ab-a928-2651f22e8899','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You have two CSV files named Products and Categories. You import the files into Power Query Editor. You need to create a Power BI dataset that will contain a single table named Product containing columns from both files. How should you combine the queries, and what should you do on the Categories query?','Merge is used to join columns from another query based on a matching key. Disabling query load prevents intermediate queries from being loaded into the memory model unnecessarily.',1,NULL,NULL,'{"rows":["Combine the queries by performing a:","On the Categories query:"],"correct_mapping":{"0":"Merge","1":"Disable the query load."}}',1788452319394);
INSERT INTO Question VALUES('345855ed-da48-45f9-b76f-4c32c4e7a757','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have an Azure SQL database that contains sales transactions updated frequently. You need to generate reports to detect fraudulent transactions with data visible within five minutes of an update. How should you configure the data connection?','DirectQuery queries the underlying data source in real time during visual rendering, ensuring updates are visible within minutes.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('a6184e93-dc3e-4002-9666-a741983449ec','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','You have a folder that contains 100 CSV files. You need to make the file metadata available as a single dataset by using Power BI without storing the CSV data itself. Which three actions should you perform in sequence?','First select Folder data source, then remove the Content column containing file contents, and finally expand Attributes to expose metadata properties.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"From Power BI Desktop, select Get Data, and then select Folder.","1":"From Power Query Editor, remove the Content column.","2":"From Power Query Editor, expand the Attributes column."}}',1788452319394);
INSERT INTO Question VALUES('ac61d46f-a08e-4358-a762-d59ce03aa46c','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','A BI developer creates a dataflow accessing an on-premises SQL Server. Enhanced Dataflows Compute Engine is enabled. You need to use the dataflow in a report to minimize online processing, render times, and include data up to the previous day. What should you do?','Creating an Import mode connection with a scheduled daily refresh caches the data in memory, satisfying rendering speed and historical data freshness needs.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('3ec7d15c-c412-4483-95fe-174f6fccd7e1','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','You publish a dataset that contains data from an on-premises Microsoft SQL Server database that must be refreshed daily. Which four actions should you perform in sequence?','Configure an on-premises data gateway, add a data source to it, assign permissions to the dataset owner, and then set the dataset refresh schedule in Power BI service.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3","Step 4"],"correct_mapping":{"0":"Configure an on-premises data gateway","1":"Add a data source.","2":"Add the dataset owner to the data source.","3":"Configure a scheduled refresh."}}',1788452319394);
INSERT INTO Question VALUES('454e042c-903b-4f22-aae4-1d228aee25a1','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You attempt to connect Power BI Desktop to a Cassandra database. From the Get Data connector list, you discover that there is no specific connector for Cassandra. Which alternate data connector should you choose?','ODBC (Open Database Connectivity) is a standard generic database driver interface used when specific native connectors are unavailable.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('7c5db452-298b-4a76-bafb-6df105d3f354','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','You receive annual sales data in Excel formatted with year headers (2019, 2020, 2021). You need to create slicers for month and year and visualize sales values over time. Which three actions should you perform in sequence?','Select Month and MonthNumber columns, execute Unpivot Other Columns to convert yearly columns into rows, then rename Attribute to Year and Value to Sales.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"Select the Month and MonthNumber columns.","1":"Select Unpivot other columns.","2":"Rename the Attribute column as Year and the Value column as Sales."}}',1788452319394);
INSERT INTO Question VALUES('a117ab52-fdcf-4941-ba66-fa3d02d84aa3','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You connect Power BI Desktop to an Azure SQL database using DirectQuery. Based on the configuration options provided, complete the default behavior statements.','By default, the connection timeout is 10 minutes. If ''Navigate using full hierarchy'' is cleared, the Navigator displays only tables containing data.',1,NULL,NULL,'{"rows":["The default timeout for the connection from Power BI Desktop to the database will be","The Navigator will display"],"correct_mapping":{"0":"10 minutes","1":"only tables that contain data"}}',1788452319394);
INSERT INTO Question VALUES('f5ec91de-a87f-4f37-9b76-438b4bbf444a','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You plan to build a single PBIX file to consume data from databases corresponding to development lifecycle stages without using deployment pipelines. What should you create and what parameter type should be used?','Creating a single parameter of type Text allows changing target server URLs or database connection strings manually per environment stage.',1,NULL,NULL,'{"rows":["Create:","Parameter type:"],"correct_mapping":{"0":"One parameter","1":"Text"}}',1788452319394);
INSERT INTO Question VALUES('1fd7d2e4-6d97-41fb-8302-70fce15b5ca7','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','multi_choice','You are creating a query to be used as a Country dimension in a star schema. The source table contains Country and City columns. The dimension must contain a list of unique countries. Which two actions should you perform?','Deleting the City column eliminates non-country attributes, and removing duplicates from the Country column ensures the dimension has unique keys.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('525a53bb-bc01-4393-80d1-7968453f65ae','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','Clean and transform a query so that all rows of data are maintained, and error values in the discount column are replaced with a discount of 0.05. Which three actions should you perform in sequence?','First select the discount column, replace error values with 0.05, and then update the data type to Decimal Number.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"Select the discount column.","1":"Select Replace Errors to replace each error value with 0.05.","2":"For the discount column, change Data Type to Decimal Number."}}',1788452319394);
INSERT INTO Question VALUES('12b0eb10-f8eb-4186-9113-4ca4b502c8e8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You encounter the error: ''Expression.Error: We cannot apply operator & to types Text and Number'' when creating a custom column. Evaluate the cause and desired outcome.','The error occurs because of mismatched data types (trying to concatenate text and integer with &). Standardizing types enables the expected output string ''A1''.',1,NULL,NULL,'{"rows":["The error is caused by","The desired outcome of the custom column is"],"correct_mapping":{"0":"mismatched data types","1":"A1"}}',1788452319394);
INSERT INTO Question VALUES('62ef90f1-d8c9-4558-baed-0a39ac0ecdc8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','From Power Query Editor, you attempt to execute a query and receive the error message ''Datasource.Error: Could not find file''. What are two possible causes of the error?','This error occurs if file permissions are denied or if the file path has changed because the file was moved.',1,NULL,NULL,NULL,1788452319394);
INSERT INTO Question VALUES('079deb90-435b-4ab7-967b-01a2246eed11','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have data in a Microsoft Excel worksheet containing columns SKU, price, and discount. Some values in the discount column contain Excel errors (#DIV/0!, #NAME?, #N/A, #NULL!, #NUM!, #REF!, #VALUE!). You need to use Power Query to clean and transform the dataset so that if the discount column returns an error, a discount of 0.05 is used, all rows are maintained, and administrative effort is minimized. What should you do in Power Query Editor?','Selecting Replace Errors replaces error values in-place across the specified column while preserving all existing dataset rows.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('1b5af768-0002-47dc-9694-9db708b08199','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have a CSV file that contains user complaints. The file contains a column named Logged formatted as ''2018-12-31 at 08:59''. You need to analyze the complaints by the logged date and use a built-in date hierarchy. What should you do?','Splitting the Logged column by ''at'' isolates the date string so that its data type can be changed to Date in Power BI, enabling built-in date hierarchies.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('e62693eb-9e70-4780-966e-e2e9302b05c7','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','drag_drop','You have two Microsoft Excel workbooks in a Microsoft OneDrive folder, each containing a table named Sales. You plan to use Power BI to combine both Sales tables into a single table and create visuals. The solution must ensure that you can publish a separate report and dataset. Which storage mode should you use for the report file and the dataset file?','Import mode is used for the report file to build visuals locally, while DirectQuery maintains a live, non-imported connection strategy for the dataset.',1,NULL,NULL,'{"dropZones":["Report file:","Dataset file:"],"correct_mapping":{"0":"Import","1":"DirectQuery"}}',1788452496622);
INSERT INTO Question VALUES('2a4d8396-4ec8-40be-a81d-15a9f9c06af4','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You use Power Query to import two tables named Order Header and Order Details from an Azure SQL database. The Order Header table relates to Order Details using Order ID. You need to combine the tables into a single query that contains the unique columns of each table. What should you select in Power Query Editor?','Merge queries combines columns from two tables based on a key column match (Order ID), similar to a SQL JOIN.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('51bd1ee9-117c-4785-9c33-7ac9f96eeda6','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have a CSV file that contains user complaints in a column named Logged formatted as ''2018-12-31 at 08:59''. You need to be able to analyze complaints by logged date using a built-in date hierarchy. What should you do?','Splitting the column by ''at'' separates date and time, enabling proper data type assignment for the date hierarchy.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('b4e9b2be-c650-4106-95ba-444d9ec5df1a','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You have a folder that contains 50 JSON files. You need to use Power BI Desktop to make the metadata of the files available as a single dataset without storing the JSON file contents. Which type of data source should you use, and which transformation should you perform?','Select Folder as the source to get file system attributes, and delete the Content column to discard actual JSON file payloads.',1,NULL,NULL,'{"rows":["Data source type:","Transformation:"],"correct_mapping":{"0":"Folder","1":"Delete the Content column."}}',1788452496622);
INSERT INTO Question VALUES('3efc5339-b0e3-4723-8ea7-870f59538faa','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','You have a PBIX file that imports data from a Microsoft Excel file share on a local network. The Excel file was moved to a new location. What are three ways to update the PBIX file to use the new location? Each correct answer presents a complete solution.','You can update local source file paths in Power BI Desktop via Data Source Settings, editing the step formula bar in Power Query, or modifying M code in Advanced Editor.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('564dc19f-6209-4d26-bd7e-bee79d95ac98','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','You have a Power BI semantic model containing sensitive Employee review data (must NOT be folded into other data sources) and Sales opportunities (less sensitive, available internally only). What privacy levels should you configure for each?','Private privacy level prevents data folding across sources to protect sensitive review data. Organizational privacy level allows controlled internal sharing across organizational sources.',1,NULL,NULL,'{"rows":["Employee review data:","Sales opportunities:"],"correct_mapping":{"0":"Private","1":"Organizational"}}',1788452496622);
INSERT INTO Question VALUES('0eb6259c-f887-4c64-bf36-6065f5f2401d','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You plan to create a bug tracking dashboard using Analytics in Azure DevOps. You need to configure a data connector in Power BI Desktop to authenticate using Analytics views and filter data from the cloud. Which connector should you use?','The Azure DevOps (Boards only) connector directly integrates with Analytics views and supports cloud-level filtering.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('b3bb0337-4c89-4829-9abe-772df61b6d24','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You preview a dataset where data always starts on row 3, and row 3 contains column names. How should you shape the query?','Use ''Remove top rows'' to remove rows 1 and 2, then select ''Use first row as headers'' to promote row 3 into column headers.',1,NULL,NULL,'{"rows":["To configure the query to start on row 3, select","To use the values in row 3 as the column names, select"],"correct_mapping":{"0":"Remove top rows","1":"Use first row as headers"}}',1788452496622);
INSERT INTO Question VALUES('a23c8c4c-6d2c-460f-a948-37be60ca818e','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A source column contains case-sensitive data in a DirectQuery semantic model resulting in undefined values and errors. Solution: You implicitly convert the values into the required type. Does this meet the goal?','Implicit type conversion does not handle case sensitivity mismatches between source engine evaluations and Power BI context.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('b3d67711-f2ab-49f6-9407-2cb0d4d19351','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A source column contains case-sensitive data in a DirectQuery semantic model resulting in undefined values and errors. Solution: You change the semantic model mode. Does this meet the goal?','Changing the storage mode does not resolve underlying case sensitivity mismatches in source values.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('2cf38675-0988-438a-bfef-f551e40d2f53','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','A source column contains case-sensitive data in a DirectQuery semantic model resulting in undefined values and errors. Solution: You normalize casing in the source query or Power Query Editor. Does this meet the goal?','Normalizing casing (e.g., converting to uppercase or lowercase) ensures consistent string comparisons across Power Query and SQL engines.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('0f3d3d82-79ca-4249-b7be-b8d7490451f9','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A source column contains case-sensitive data in a DirectQuery semantic model resulting in undefined values and errors. Solution: You add an index key and normalize casing in the data source. Does this meet the goal?','Adding an index key preserves uniqueness while casing normalization resolves context mismatch errors.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('c73b6ccc-58ca-4dbc-ab73-dd795a2cc9ca','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','You have an Excel file in OneDrive for Business that must be imported into Power BI and refreshed in powerbi.com. Which two connectors can you use? Each correct answer presents a complete solution.','Web connector (using the direct file link) and SharePoint folder connector both natively support automated web refreshes in Power BI Service without gateways.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('e83724a7-981f-49fd-bf4a-315fc915c1bb','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You preview a Date column containing full date values. You need to change the Date column to contain only the year with minimal administrative effort. What should you do?','Using the built-in Power Query Date transformation tool (Date -> Year) instantly transforms the column values to year integers with minimal steps.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('649a9792-171b-4b98-b127-6a1672020c63','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','You are designing a data model containing Date, Patient, Test, and Test Result tables. Which table is the fact table, and which column in Patient is the surrogate key?','Test Result contains quantitative measurement transactions and foreign keys, making it the Fact table. Patient key is the unique surrogate identifier for the Patient dimension.',1,NULL,NULL,'{"rows":["Fact table:","Surrogate key:"],"correct_mapping":{"0":"Test Result","1":"Patient key"}}',1788452496622);
INSERT INTO Question VALUES('e622b73e-3d6c-44c2-8f4f-907415bcc139','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You import Customer and Contacts tables. Contacts contains unsanitized customer names filled via a web form. You need to merge Customer and Contacts tables. What should you do?','Enabling fuzzy matching allows Power Query to perform approximate string matching across unsanitized text fields.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('26669ba3-fa33-4dd1-bd6a-0e5c1711b256','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You load a free text field named col1 and need to analyze the frequency distribution of string lengths in col1 without affecting the model size. What should you do?','In Power Query Editor, enabling Column Profile and grouping by text length inspects string distributions in memory without persisting calculated columns to the dataset.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('7976aa9e-ac49-4a89-a0a5-58d57133cc4d','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','single_choice','HR managers must interact with data from their sales region only using RLS and must be prevented from changing report layouts. How should you provision access?','Publishing the report via an App grants view/interaction permissions while preventing layout modifications inherent to workspace editor roles.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('cf7f871c-69ad-4e2d-bd46-c88d4199f95b','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','single_choice','You need to provide a user with the ability to add members to a Power BI workspace using the principle of least privilege. Which role should you assign?','The Member role can add users or assign lower permissions (Contributors/Viewers), whereas Admin grants full control including deletion.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('a3661706-121a-4719-9f18-00401b283f23','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','multi_choice','You have a query named Sales. Users only analyze dates and rows where Status is Finished. You need to reduce query load times without affecting analysis. Which two actions achieve this? Each correct answer presents a complete solution.','Removing canceled rows reduces dataset row volume, and removing Canceled_Date or splitting Date/Time types optimizes storage engine compression.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('c9a0d6d4-ba02-494f-8b19-84440a0a07f1','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You import Customer (CustomerID primary key) and Transaction (TransactionID primary key, CustomerID foreign key). Which relationship should link the tables?','The primary key side (Customer) maintains a 1 cardinality while foreign key transactions maintain a Many cardinality.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('423d63e9-71fb-4783-b954-0080b3b56699','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You need to prevent report recipients from reading internal email Subject and Body text while minimizing model size. What should you do?','Removing unused sensitive columns during import drops them from the model entirely, securing the data and shrinking model footprint.',1,NULL,NULL,NULL,1788452496622);
INSERT INTO Question VALUES('4224f678-f25a-49c0-a207-19a09f5f59a8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','matrix','Configure table properties to make a dataset table available as an organizational data type in Excel.','Row label defines the displayed header, Key column provides unique row identification for Excel links, and Is featured table must be set to Yes.',1,NULL,NULL,'{"rows":["Row label:","Key column:","Is featured table:"],"correct_mapping":{"0":"Name","1":"ID","2":"Yes"}}',1788452496622);
INSERT INTO Question VALUES('b603680b-5e32-428b-b2cc-d5970b934728','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','multi_choice','You have a Power BI model with Country, Calendar, Purchase, and Purchase Detail tables. A manager can represent only a single country. You need to use row-level security (RLS) to ensure managers see only data for their country while minimizing the number of RLS roles. Which two actions should you perform? Each correct answer presents a complete solution.','Filtering Country[Manager_Email] with USERNAME() dynamically restricts data based on the logged-in user without requiring multiple roles. Enabling bidirectional security filtering between Purchase Detail and Purchase propagates the dynamic security filter across related tables.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('fd57b919-fccf-4f15-91d8-3cdf38f6144a','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','You have a Power BI imported dataset containing an Employee fact table surrounded by multiple dimension tables. Evaluate the data model settings and architecture.','Modifying the Cross filter direction of relationships reduces unnecessary bidirectional filtering overhead and improves report query performance. The central fact table surrounded by single-level dimension tables forms a star schema.',1,NULL,NULL,'{"rows":["Changing the [answer choice] setting of the relationships will improve report query performance.","The data model is organized into a [answer choice]."],"correct_mapping":{"0":"Cross filter direction","1":"star schema"}}',1788452584189);
INSERT INTO Question VALUES('db817739-2337-4134-aedb-ba31d11f311d','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','You have a Power BI model with a Sales table and a related Date table. Sales contains a measure named Total Sales. You need to create a measure that calculates total sales from the equivalent month of the previous year. How should you complete the calculation?','CALCULATE modifies filter context using SAMEPERIODLASTYEAR applied over the contiguous date column ''Date''[Date].',1,NULL,NULL,'{"rows":["Function 1","Function 2","Column"],"correct_mapping":{"0":"CALCULATE","1":"SAMEPERIODLASTYEAR","2":"''Date'' [Date]"}}',1788452584189);
INSERT INTO Question VALUES('11b35502-1d7e-4cdc-8312-1c45c8cbb707','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','drag_drop','You plan to create a report to restrict access to individual rows of data on a per-region basis using roles. Which four actions should you perform in sequence?','First import data into Power BI Desktop, define security roles in Desktop, publish the report to Power BI service, and finally assign users to roles within the Service.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3","Step 4"],"correct_mapping":{"0":"Import the data to Power BI Desktop.","1":"Create a role definition.","2":"Publish the report.","3":"Assign users to the role."}}',1788452584189);
INSERT INTO Question VALUES('edaf3d6b-82e6-4023-a978-b26e40a76671','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','You need to denormalize Sales_Region, Region_Manager, Sales_Manager, and Manager tables into a single table in Power Query. Only managers associated with a sales region must be included. Which three actions should you perform in sequence?','Merge Region_Manager and Manager using an inner join to keep only valid region managers, merge Sales_Region and Sales_Manager using inner joins, and combine into a single query.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"Merge [Region Manager] and [Manager] by using an inner join.","1":"Merge [Sales Region] and [Sales_Manager] by using an inner join.","2":"Merge [Sales Region] and [Region Manager] by using an inner join."}}',1788452584189);
INSERT INTO Question VALUES('b400955d-b412-480d-8f3b-488588c0974a','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','A single-page Power BI report contains 25 visuals and performs slowly when users access and interact with it. What should you recommend to improve performance?','Splitting visual elements across multiple report pages reduces concurrent rendering queries and improves page responsiveness.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('e963a09f-d7a2-4254-8f52-b7de0a4567ca','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','Evaluate optimizing a Sales fact table for product basket analysis across sales territories. Select Yes if the statement is true; otherwise, select No.','SalesRowID and AuditID are non-analytical system IDs that can be removed. OrderDateKey is redundant when OrderDate exists. TaxAmt decimal precision does not impact item affinity calculations.',1,NULL,NULL,'{"rows":["The SalesRowID and AuditID columns can be removed from the model without impeding the analysis goals.","Both the OrderDateKey and OrderDate columns are necessary to perform the basket analysis.","The TaxAmt column must retain the current number of decimal places to perform the basket analysis."],"correct_mapping":{"0":"Yes","1":"No","2":"No"}}',1788452584189);
INSERT INTO Question VALUES('1f9c03a3-8a3a-4966-a394-6f3bad7490f5','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A user is assigned to Role1 (State Province = Kentucky) and Role2 (Calendar Year = 2020). What data will they see in a report that uses the model?','When a user belongs to multiple RLS roles, the security filters are additive (Filter A OR Filter B).',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('de475f11-3cc3-4e10-8cb2-756f9b9ee679','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You need to import a sample of data from a SQL Server table with over 100 million records during development. Solution: Import the table into Power Query and add a filter step. Does this meet the goal?','Filtering in Power Query after importing still pulls all rows initially; filtering must happen at source evaluation via SQL WHERE clause or native query.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('e5aaef7e-6ce4-42dc-8057-a52586a124bb','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','You need to import a sample of data from a SQL Server table with over 100 million records during development. Solution: Write a DAX expression that uses the FILTER function. Does this meet the goal?','DAX FILTER evaluates data after it has already been loaded into the model, failing to reduce initial data transfer from the database.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('adfc8848-38fc-4c08-b461-c4e922606461','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You need to import a sample of data from a SQL Server table with over 100 million records during development. Solution: Add a WHERE clause to the SQL statement in Advanced options. Does this meet the goal?','Adding a WHERE clause to the source query filters records on the database engine, returning only the required sample rows.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('b4f72fa4-3c09-48aa-a81a-8d22cbdab3e5','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','Prepare Excel financial data with yearly columns (2016 to 2020) for visual analysis and year-over-year calculations. Which four actions should you perform in sequence?','Promote headers, unpivot yearly columns except Measure, rename the Attribute column to Year, and set the Year data type to Date.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3","Step 4"],"correct_mapping":{"0":"Use the first row as headers.","1":"Unpivot all the columns other than Measure.","2":"Rename the Attribute column as Year.","3":"Change the data type of the Year column to Date."}}',1788452584189);
INSERT INTO Question VALUES('bbefca5f-1abe-4a4e-b73c-35a0ec9ecccd','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','You are optimizing a model with Sales and Employee tables. There is a relationship on employee_id, and no reporting requirements exist for employee_id and employee_photo. How should you configure employee_id and employee_photo?','Employee_id is required for relationship integrity and should be hidden. Employee_photo is unused and should be deleted to save memory.',1,NULL,NULL,'{"rows":["Employee_id:","Employee_photo:"],"correct_mapping":{"0":"Hide","1":"Delete"}}',1788452584189);
INSERT INTO Question VALUES('e76dd91f-f0e1-45ea-ae51-493a3943eeb1','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','Design a star schema model from school attendance views View1 and View2. In which table should you include Teacher First Name and Period Number fields?','Teacher First Name belongs in the Teacher dimension. Period Number forms part of the class schedule metadata and belongs in the Class dimension.',1,NULL,NULL,'{"rows":["Teacher First Name:","Period Number:"],"correct_mapping":{"0":"Teacher dimension","1":"Class dimension"}}',1788452584189);
INSERT INTO Question VALUES('aded87c7-df58-4d47-8e74-7cb537f418f4','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You have a Departments table related to ConfidentialData. You need to ensure users see data of their respective department only. What should you do?','Creating Row-Level Security (RLS) roles with dynamic or explicit filters restricts row access based on user credentials.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('2130bd20-7368-464e-bcce-c16d79b96063','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You have two tables with RLS configured. You need to create a relationship ensuring bidirectional cross-filtering honors RLS settings. What should you do?','Checking ''Apply security filter in both directions'' on an active relationship enforces RLS filters across both sides of the relationship.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('50d63122-ac2f-439c-92f4-325a06dd4938','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','matrix','UnitsInStock has 75 non-null values, of which 51 are unique. Predict the visual behaviors when added to a table visual.','A unsummarized table visual displays all 75 rows. Changing Summarize by aggregates identical rows, reducing row count in the visual.',1,NULL,NULL,'{"rows":["When a table visual is created in a report and UnitsInStock is added to the values, there will be [answer choice] in the table.","Changing the Summarize by setting of the UnitsInStock column, and then adding the column to a table visual, will [answer choice] the number of rows in the table visual."],"correct_mapping":{"0":"75 rows","1":"reduce"}}',1788452584189);
INSERT INTO Question VALUES('32f39bb7-f84e-4cd9-92de-8f5297efa505','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Evaluate the measure ''Accounts := CALCULATE(DISTINCTCOUNT(Balances[AccountID]), LASTDATE("Date"[Date]))'' against daily snapshot balance data across date hierarchy levels. Select Yes if true; otherwise, No.','LASTDATE evaluates the final date within the given filter context. At Year and Month levels, it returns active accounts on the last day of the period, not throughout. At the Day level, it returns accounts active on that day.',1,NULL,NULL,'{"rows":["A table visual that displays the date hierarchy at the year level and the [Accounts] measure will show the total number of accounts that were live throughout the year.","A table visual that displays the date hierarchy at the month level and the [Accounts] measure will show the total number of accounts that were live throughout the month.","A table visual that displays the date hierarchy at the day level and the [Accounts] measure will show the total number of accounts that were live that day."],"correct_mapping":{"0":"No","1":"No","2":"Yes"}}',1788452584189);
INSERT INTO Question VALUES('46f861c6-dee2-43b2-9cb5-4207a797da03','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','multi_choice','Impressions table has 30M records/month. You need to show ad impressions by day, campaign, and site_name for the last year while minimizing model size. Which two actions should you perform?','Creating relationships establishes standard dimensional modeling. Grouping and summarizing the Impressions query in Power Query reduces row counts significantly before loading into memory.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('fe1b97fc-933b-4cc8-86a3-4c183b08fb24','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','Configure relationship properties between ProductCategory and Products tables. Each product has one product category.','One category maps to multiple products (One-to-many). Single cross-filter direction optimizes query execution performance.',1,NULL,NULL,'{"rows":["Cardinality:","Cross-filter direction:"],"correct_mapping":{"0":"One-to-many","1":"Single"}}',1788452584189);
INSERT INTO Question VALUES('a74fec0f-56dd-464e-84cd-9b99c0c6bc14','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','Product Inventory table contains 25M rows with DateKey, MovementDate, UnitCost, UnitsIn, UnitsOut, UnitsBalance. DateKey relates to Date. How can you reduce model size without losing information?','MovementDate duplicates information already represented by DateKey; removing it frees significant memory.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('b7997cd0-b289-4397-8426-7bf756611ab5','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the DAX measure returning year-to-date total sales from the same date of the previous calendar year.','CALCULATE modifies the SUM context using DATESBETWEEN across computed start and end dates.',1,NULL,NULL,'{"rows":["Function 1","Function 2","Function 3"],"correct_mapping":{"0":"CALCULATE","1":"SUM","2":"DATESBETWEEN"}}',1788452584189);
INSERT INTO Question VALUES('509d351f-31c8-4463-9deb-76d9cea025ce','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You need to import a sample of data from an Order table with 100M rows during development. Solution: Add a report-level filter based on order date. Does this meet the goal?','Report-level filters execute after data is imported into memory, failing to reduce network payload or import time.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('2ca7a71c-e3fd-431e-9778-07a047c9a011','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','Sales table has foreign keys Due Date, Order Date, Delivery Date. Solution: Add inactive relationships for each date foreign key to support analysis. Does this meet the goal?','Inactive relationships require USERELATIONSHIP DAX measures to filter data; simply adding them without DAX logic does not fulfill analysis needs.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('b12bbac3-69bd-456a-a9a4-2bf5d2ec9b02','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','Sales table has foreign keys Due Date, Order Date, Delivery Date. Solution: Reference the Date query twice in Power Query to create Order Date and Delivery Date queries. Does this meet the goal?','Creating separate role-playing dimension tables enables active relationships between Sales and each date dimension.',1,NULL,NULL,NULL,1788452584189);
INSERT INTO Question VALUES('54ffe6e6-f9c4-4208-ad24-fa9cfdd999a8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You have a Power BI report that imports a date table and a sales table from an Azure SQL database data source. The sales table has foreign keys: Due Date, Order Date, and Delivery Date. Solution: From the Fields pane, you rename the date table as Due Date. You use a DAX expression to create Order Date and Delivery Date as calculated tables. Does this meet the goal?','Creating calculated tables for role-playing dimensions creates dedicated dimension tables, allowing active relationships to be established for simultaneous time analysis.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('0694fbe7-461f-47b4-875c-97b0fd0cf668','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','You receive revenue data with Department, Product, and year columns (2016, 2017, 2018, 2019). You need to transform the data to show revenue split by year and product. Which three actions should you perform in sequence?','Promote the top row to headers, select Department and Product to unpivot other columns, and rename Attribute to Year and Value to Revenue.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"Select Use First Row as Headers.","1":"Select Department and Product and Unpivot Other Columns.","2":"Rename the Attribute column to Year and the Value column to Revenue."}}',1788452621419);
INSERT INTO Question VALUES('8220125a-dc66-4722-88bd-b751e0740c62','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','Evaluate actions to reduce the data model size of an Orders table while supporting analysis for total sales over time, count of orders, and new/repeat customer counts.','Summarizing Orders by CustomerID/OrderID/OrderDate does not reduce size effectively for total sales. CustomerID is required to track new vs. repeat customers. UnitPrice and Discount are redundant since SalesTotal is available.',1,NULL,NULL,'{"rows":["Summarizing Orders by the CustomerID, OrderID, and OrderDate columns will reduce the model size while still supporting the current analysis.","Removing the CustomerID column from Orders will reduce the model size while still supporting the current analysis.","Removing the UnitPrice and Discount columns from Orders will reduce the model size while still supporting the current analysis."],"correct_mapping":{"0":"No","1":"No","2":"Yes"}}',1788452621419);
INSERT INTO Question VALUES('9dddc89e-c55d-4e21-9890-1b8f69506327','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the DAX measure calculation to determine the relative change in sales compared to the previous quarter.','CALCULATE evaluates the sales sum filtered by DATEADD set back by -1 QUARTER. DIVIDE measures relative quarter-over-quarter growth.',1,NULL,NULL,'{"rows":["Function 1","Function 2","Function 3"],"correct_mapping":{"0":"CALCULATE","1":"DATEADD","2":"DIVIDE"}}',1788452621419);
INSERT INTO Question VALUES('7cf4864b-efcb-452d-9ba2-d4597ddcd6af','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','drag_drop','Complete the DAX expression to create a calculated table showing the top eight products based on highest Total Sales.','TOPN evaluates a table context to return the top N rows based on an order-by expression, specifying DESC for highest values.',1,NULL,NULL,'{"dropZones":["Function","Order Direction"],"correct_mapping":{"0":"TOPN","1":"DESC"}}',1788452621419);
INSERT INTO Question VALUES('ecd87173-6fea-4b14-b7d5-bb0d55be0435','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','You are creating a sales report for the NorthWest territory from a SQL Server view. You need to reduce refresh times and query times. Which two actions should you perform? Each correct answer presents part of the solution.','Removing unreferenced metrics (TaxAmt and Freight) reduces memory, and filtering specifically to NorthWest limits dataset row size.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('747f7b6b-15ff-4590-97c3-6240f2481015','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You plan to create a map visual showing store locations with drill-down capability from Country to State/Province to City. What should you do to ensure locations map properly?','Categorizing text fields with proper Data Categories (Country, State/Province, City) allows Power BI map engine to accurately plot geographic points.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('e6d1df4c-2e46-4f3a-a7e9-54f0da62fbb8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have data in a Machine-User column formatted as ''ABC-123''. You need to split Machine and User to display them in a clustered bar chart. What should you do?','Splitting the text column by hyphen delimiter in Power Query separates Machine identifiers and User IDs into clean dimensional attributes.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('3d4521ac-c804-4b5f-8c73-f81b0291d018','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','drag_drop','Complete the DAX code to create a date table containing 10 full calendar years, including the current year.','YEAR(TODAY()) obtains the current year, and CALENDAR generates a contiguous table of dates between calculated start/end dates.',1,NULL,NULL,'{"dropZones":["Function 1","Function 2","Function 3"],"correct_mapping":{"0":"YEAR","1":"TODAY","2":"CALENDAR"}}',1788452621419);
INSERT INTO Question VALUES('0958771f-acaf-4016-93de-a1d5a1d22699','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','Sales table has foreign keys: Due Date, Order Date, Delivery Date. Solution: Create measures using USERELATIONSHIP to filter sales on the active relationship. Does this meet the goal?','USERELATIONSHIP can only be applied to activate an inactive relationship within DAX measures, not on already active relationships.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('7aa3ba3e-6f27-4555-9081-f309c104a887','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the DAX expression to return the sum of Total Sales for a year up to a selected date.','TOTALYTD evaluates an expression over year-to-date intervals using a contiguous date column reference.',1,NULL,NULL,'{"rows":["Function","Column"],"correct_mapping":{"0":"TOTALYTD","1":"''Date''[Date]"}}',1788452621419);
INSERT INTO Question VALUES('7860fc00-6dbd-4351-bfae-88b2688fbf33','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','drag_drop','Complete the DAX calculated column code to classify transaction sales amounts into size segments matching the Transaction Size table.','FILTER checks min/max criteria joined logically with AND, and CALCULATE evaluates DISTINCT values.',1,NULL,NULL,'{"dropZones":["Function 1","Operator","Function 2"],"correct_mapping":{"0":"FILTER","1":"AND","2":"CALCULATE"}}',1788452621419);
INSERT INTO Question VALUES('eac107ed-c45b-4b80-9106-62c13057f92b','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You have a procurement report containing Suppliers (100k rows) and LineItems (1B rows). You need to minimize dataset size without affecting visuals. What should you do?','LineItems[Description] is an unreferenced high-cardinality text column; removing it drastically minimizes the dataset footprint.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('7e6e5a74-289d-48c9-b0b2-2a8abf80c933','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','A marketing report on blog traffic refresh takes a long time. Which two actions reduce query load times? Each correct answer presents part of the solution.','Filtering Traffic rows that don''t contain ''blog'' discards non-relevant website traffic, and dropping Full Text and Summary from Posts removes heavy unneeded text payload.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('3f612cd7-5d8e-4323-86dd-cd546171ec91','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Configure quick measure parameter parameters to calculate a monthly rolling average of Sales over time.','Base value is Total Sales, Date defines the timeline field, and Period specifies Months for monthly rolling calculations.',1,NULL,NULL,'{"rows":["Base value:","Date:","Period:"],"correct_mapping":{"0":"Total Sales","1":"Date","2":"Months"}}',1788452621419);
INSERT INTO Question VALUES('fa9038db-c68e-499a-8320-5c0fb1f34e51','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','You plan to create a measure to return total sales of March 2021 when March 2022 is selected in a visual. Which DAX expression should you use?','CALCULATE combined with SAMEPERIODLASTYEAR shifts the filter context back by exactly one year.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('2a865069-2359-4ab7-bb7c-dab3d62cd0f5','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','While loading data from SQL Server, you experience long loading times and timeouts. What are two ways to resolve the issue? Each correct answer presents a complete solution.','Filtering out unwanted rows/columns minimizes transfer payload, and splitting long queries reduces concurrency stress on source systems.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('48cdabec-ec04-436d-8483-dcb163a88b20','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You need to analyze IoT events by hour and day of the year. Solution: You split the IoT DateTime column into separate Date and Time columns. Does this meet the goal?','Separating date and time values reduces distinct column cardinality, optimizing data compression and performance.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('89daf8b7-4dae-431d-a989-2ef500ca2fa5','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','Both IoT GUID and IoT ID are unique per row. You need to analyze IoT events by hour and day of the year. Solution: Remove IoT GUID and retain IoT ID. Does this meet the goal?','Removing a high-cardinality text GUID column while keeping an integer ID reduces memory footprint significantly without losing row identity.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('8afefbc6-2415-464d-a5ed-f9fb3002edee','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You need to analyze IoT events by hour and day of the year. Solution: Change the IoT DateTime column to the Date data type. Does this meet the goal?','Converting DateTime directly to Date strips out time details, making hourly analysis impossible.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('7acfae81-b905-474c-ae54-45221e6e8fcf','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A 550MB report with 12 million rows is slow to load visuals. What performance optimization should you recommend?','Removing unused columns improves storage compression in the VertiPaq engine and speeds up memory scan performance.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('a13c2b65-181c-4230-92cf-e783d542361a','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','drag_drop','Complete the DAX measure to return percent of total sales for each product, respecting report-level filters.','CALCULATE modifies evaluation context, and ALLSELECTED calculates total across visual rows while respecting outer slicer/report filters.',1,NULL,NULL,'{"dropZones":["Function 1","Function 2"],"correct_mapping":{"0":"CALCULATE","1":"ALLSELECTED"}}',1788452621419);
INSERT INTO Question VALUES('8fa843ad-3aa8-4a55-8788-adc7c6cd7c08','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','multi_choice','You need to reduce data model size while maintaining ability to analyze product sales by month and quarter. Which two actions should you perform?','Disabling auto date/time removes automated hidden date hierarchies. Explicitly building and marking a Date table preserves custom date analyses.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('89379f8c-815c-489a-bfd4-bbfc6f29e3cb','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A Power BI report with 12 million rows is slow to render visuals. Which recommendation directly addresses memory footprint?','Removing unreferenced columns reduces memory consumption, yielding immediate performance gains in visual rendering.',1,NULL,NULL,NULL,1788452621419);
INSERT INTO Question VALUES('b4e16cd0-7c00-4c2e-a37f-2a39ea36d075','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the calculated column DAX expression to return ''Inactive - '' concatenated with Store Name when Status is not ''A''.','The IF statement evaluates whether status equals ''A''. The string concatenation operator (&) appends the prefix to inactive stores.',1,NULL,NULL,'{"rows":["Function","Operator"],"correct_mapping":{"0":"IF","1":"&"}}',1788452621419);
INSERT INTO Question VALUES('371faaf7-0cd9-423a-b91d-1f48ea3ee9a3','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have a CSV file containing user complaints. Logged is formatted as ''2018-12-31 at 08:59''. You need to analyze complaints by logged date using a built-in date hierarchy. What should you do?','Adding a Column by Example extracting ''2018-12-31'' and explicitly casting its data type to Date generates a valid date field, enabling built-in date hierarchies.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('5435727e-393b-4c6f-bd2a-fac95b4205af','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','Both IoT GUID and IoT ID are unique per row in a query. You need to analyze IoT events by hour and day of the year. Solution: You create a custom column concatenating IoT GUID and IoT ID, then delete the original columns. Does this meet the goal?','Concatenating unique keys creates a long text string, increasing cardinality and memory usage without aiding performance.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('e17ae7c6-a0bb-4664-bfea-6f96429b8ad8','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','You have an Employee table where each employee has a manager listed in ParentEmployeeID. You need to create a calculated column that returns the count of organizational hierarchy levels from each employee to the CEO. Which DAX expression should you use?','PATHLENGTH combined with PATH evaluates the total number of parent/child hierarchy levels for a given row.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('798526b0-f2d9-41b9-91b2-c5768f2b67e9','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A Power BI report with 12 million rows is slow to load visuals. What should you recommend to improve performance?','Deleting unreferenced columns reduces dataset size and memory footprint, which improves visual rendering speeds.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('cb9de20f-96da-4dbf-a800-19bb96300279','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You have a Logged column formatted as ''2018-12-31 at 08:59''. You need to analyze complaints by logged date using a built-in date hierarchy. What should you do?','Splitting the column by ''at'' isolates the date component, allowing it to be cast as a Date type to enable date hierarchies.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('9c98f89b-7a5b-48ea-8bdb-2dce04401a9e','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the DAX expression to count the number of product categories that had products sold during a selected period.','DISTINCTCOUNT evaluates unique product categories, while filtering against the Sales fact table restricts output to categories with active transactions.',1,NULL,NULL,'{"rows":["Function","Filter Table"],"correct_mapping":{"0":"DISTINCTCOUNT(''Product''[product category])","1":"''sales''"}}',1788452673486);
INSERT INTO Question VALUES('817da210-72e6-4341-bf18-22566cc4e7b9','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','A 550MB report with 12 million rows experiences slow visual loading times. What should you recommend to improve performance?','Removing unused columns optimizes memory layout and compression in VertiPaq, accelerating visual render performance.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('973cb631-0252-489f-bd91-3b22dbda5491','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','Evaluate whether removing specified columns from the Sales table reduces model size while still supporting required order-based analyses. Select Yes or No.','LastUpdated and ShipDate are not needed for order date analysis and can be removed. ProductID is required to relate Sales to Products for product-level analysis.',1,NULL,NULL,'{"rows":["Removing LastUpdated reduces model size while supporting required analysis.","Removing ProductID reduces model size while supporting required analysis.","Removing ShipDate reduces model size while supporting required analysis."],"correct_mapping":{"0":"Yes","1":"No","2":"Yes"}}',1788452673486);
INSERT INTO Question VALUES('04c6650a-b55c-43b9-9f34-528816370f53','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You need to analyze complaints formatted as ''2018-12-31 at 08:59'' by logged date using a built-in date hierarchy. What should you do?','Creating a column by example extracting ''2018-12-31'' and setting the data type to Date generates a valid date field for date hierarchies.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('af5037f5-50e0-4260-a1c5-3f24cfb0c3df','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You are implementing dynamic row-level security (RLS) on an Employees table. Users must see only their own employee data. The expression must work in Desktop and Service. Which expression should you use?','[Email Address] = USERPRINCIPALNAME() matches the logged-in user''s UPN against their record in both Power BI Desktop and Service.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('cbad5928-4339-40c0-9c52-b539fc27e955','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','drag_drop','You create RLS roles Manager and CFO. Managers see Sales and HR for their own country. The CFO cannot see HR data but must see Sales for all countries. How should you complete the DAX expressions?','Setting HR filter to False() restricts the CFO from seeing any HR rows. Setting Country filter to [Email] = USERPRINCIPALNAME() restricts managers to their country.',1,NULL,NULL,'{"dropZones":["Human Resources Filter","Country Filter"],"correct_mapping":{"0":"False()","1":"[Email] = USERPRINCIPALNAME()"}}',1788452673486);
INSERT INTO Question VALUES('c7589404-31ea-4b4b-8763-b3acf139b1c1','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','You receive ''Expression.Error: The column ''Category'' of the table wasn''t found'' when reloading a query from Excel. What are two possible causes? Each correct answer presents a complete solution.','If the source column was removed or renamed in Excel, Power Query fails during refresh when attempting to apply steps referencing the original name.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('0147db13-5fe4-40ef-9d1c-5149c498acdd','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','Orders are uniquely identified by Order ID and can have multiple order lines. You need to write a DAX measure that counts the total number of orders. Which formula should you use?','DistinctCount(''Sales''[Order ID]) counts unique order IDs, ensuring multi-line orders are counted as a single order.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('e6787fd5-9d11-44a6-a43e-051caa0b8364','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the DAX expression to create a calculated table named Numbers containing all integers from -100 to 100.','GENERATESERIES generates a single-column table with numbers starting at start_value, ending at end_value, incremented by step_size.',1,NULL,NULL,'{"rows":["Function","Parameters"],"correct_mapping":{"0":"GENERATESERIES","1":"-100, 100, 1"}}',1788452673486);
INSERT INTO Question VALUES('4c44d303-e023-4679-aefa-940024d9b7b6','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You are implementing dynamic RLS on an Employees table. Users must see only their own data. The expression must work in Desktop and Service. Which expression should you use?','[Email Address] = USERPRINCIPALNAME() matches user credentials consistently across Desktop and Service environments.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('db8e30f4-0f06-4c9e-b931-9e5d68201936','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','You need to create a calculated table based on a Date table that contains unique combinations of Calendar Year, Calendar Quarter, and Calendar Month. Which DAX function should you include?','SUMMARIZE creates a summarized table grouped by specified columns, returning unique combinations of group-by fields.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('b2c51dfc-2367-4183-adea-98fdf6b77159','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the DAX calculated table formula to return a row for each year and a column with total sales per year.','SUMMARIZE groups the Sales table by Date[Year] and calculates SUM(Sales[SalesAmount]) as ''Total Sales''.',1,NULL,NULL,'{"rows":["Function","Group By Column","Aggregation"],"correct_mapping":{"0":"SUMMARIZE","1":"Date[Year]","2":"SUM(Sales[SalesAmount])"}}',1788452673486);
INSERT INTO Question VALUES('88697e0f-60f1-436f-99a6-2f68b0893e30','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','Sales data from 2020 and 2021 is arranged in separate columns in an Excel import. You need to shape the query into three columns: Month, Sales, Year. What should you select?','Selecting the 2020 and 2021 columns and applying Unpivot Columns transforms attribute headers into rows for Month, Sales, and Year.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('6b282064-9fdc-4ecb-8161-758fece32ecf','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the DAX measure to show the last recorded inventory value for a given month, year, or date.','CALCULATE modifies evaluation context using LastDate(''Date''[Date]), and SUM retrieves the QuantityAvailable on that final date.',1,NULL,NULL,'{"rows":["Function 1","Function 2"],"correct_mapping":{"0":"CALCULATE","1":"LastDate"}}',1788452673486);
INSERT INTO Question VALUES('b8241294-7438-45b8-ba3e-508600fe779e','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','Sales table has Due Date, Order Date, Delivery Date foreign keys. Solution: Rename Date as Due Date, create Order Date and Delivery Date as calculated tables, and create active relationships to each. Does this meet the goal?','Role-playing dimension calculated tables allow active relationships between the fact table and each individual date dimension, supporting simultaneous temporal analysis.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('4705d1c4-c67d-49b9-9497-3918ff799f49','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','Complete the semi-additive DAX measure returning the headcount for the last available date in a year, quarter, or month.','CountRows(''Headcount'') calculates employee count, while LastDate(Headcount[''DateKey'']) filters the calculation context to the final available snapshot date.',1,NULL,NULL,'{"rows":["Expression","Filter Function"],"correct_mapping":{"0":"CountRows(\"Headcount\")","1":"LastDate(Headcount[\"DateKey\"])"}}',1788452673486);
INSERT INTO Question VALUES('a9c49ef6-a88e-44dd-a2a0-4ba9631eba81','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You plan to use ''All Sales'' query as the source for Sales Fact, Product Dimension, and Customer Dimension queries while minimizing maintenance effort. What should you do to create Sales Fact, and for which query should you clear Enable Load?','Referencing ''All Sales'' reuses M transformations for downstream queries. Clearing Enable Load on ''All Sales'' prevents staging data from loading into model memory.',1,NULL,NULL,'{"rows":["Creation action:","Clear Enable load for:"],"correct_mapping":{"0":"Reference the All Sales query.","1":"All Sales."}}',1788452673486);
INSERT INTO Question VALUES('ed481a44-a326-4b74-bc33-c5616595a68d','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','You have a Total Sales measure. You need to create a Previous Quarter measure to display sales one quarter before the selected period. Which DAX calculation should you use?','CALCULATE([Total Sales], DATEADD(Date[Date], -1, QUARTER)) shifts the date filter context back by one full quarter relative to the selection.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('4c6a2c08-4e6a-41c5-9224-de7010dd44e2','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','A single-page Power BI report contains 25 visuals and performance is slow. What should you recommend to improve performance?','Splitting visuals onto multiple report pages reduces initial load time and visual query concurrency.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('cc70db83-9f5d-4ef9-93d7-bbe9a69e4d35','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','A calculated table is defined as ProductList = INTERSECT(ProductsGroupA, ProductsGroupB). Which rows will be returned?','INTERSECT returns the row-level intersection between two tables, retaining rows in the left table that match the right table.',1,NULL,NULL,NULL,1788452673486);
INSERT INTO Question VALUES('a676bf4a-ec6a-4c31-9221-bfcba3be7351','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You have a Power BI data model containing Sales and Date tables with measures Order Quantity, Product Cost, and Sales Amount. You need to display the measures in the row headers of a matrix visual. In which section of the Fields well should you place the measures?','Adding measures or a field parameter to the Values section of a Matrix visual allows you to configure ''Switch values to rows'' in formatting options to display measures as row headers.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('48bfed46-3d70-42df-8488-43d98dac9d68','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','matrix','You have a Power BI report with implicit DAX measures used across visuals. How should you replace the implicit measures and control default field aggregations?','Implicit measures are replaced by creating explicit DAX measures. Controlling how a numeric fieldaggregates by default across visuals is configured using the Summarization setting.',1,NULL,NULL,'{"rows":["To replace all the implicit DAX measures used in the visual:","To change how the Product Cost field is aggregated in additional visuals:"],"correct_mapping":{"0":"Two explicit measures","1":"Summarization setting"}}',1788452722549);
INSERT INTO Question VALUES('e12d44e0-b7b3-45ac-88af-02b735d6761e','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','You have an Employees table containing Employee ID, First Name, Last Name, Department, and Salary. You need to create a DAX measure that calculates the average salary of all employees in the Sales department. Which DAX expression should you use?','CALCULATE modifies the filter context so that AVERAGE(''Employees''[Salary]) evaluates specifically where ''Employees''[Department] = ''Sales''.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('ad5002d4-3672-4213-ae7f-1690fbffd782','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You preview sales order data containing Tax Amount, Sales Order ID, Freight Amount, Subtotal Amount, and Total Item Quantity. Freight Amount is null when no freight is charged. How should you modify the query to accurately measure average freight amount per order?','Replacing null values with 0 in Freight Amount ensures that orders without freight charges are included as zero in average calculations rather than being omitted.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('55ef6662-3792-44a4-881a-b7a85bd4b875','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','In the source system, not every customer has an address, but every address has a country. You need to merge Customers, Address, and Country queries into a single query while optimizing refresh performance. Which join types should you use?','Joining Customers to Address requires a Left Outer join to retain all customers regardless of address presence. Joining Address to Country uses an Inner join as every address maps to a valid country.',1,NULL,NULL,'{"dropZones":["Join Customers with Address:","Join Address with Country:"],"correct_mapping":{"0":"Left Outer","1":"Inner"}}',1788452722549);
INSERT INTO Question VALUES('52af2441-a85a-4650-b332-7d4e43d150e0','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','Query1 loads customer data and is referenced by Query2, Query3, and Query4. Refresh for the model is slow. You need to improve data refresh time while minimizing costs. What should you do?','Applying Table.Buffer in Query1 caches the query output in memory, avoiding repeated source evaluations when referenced downstream.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('3c1584ed-2c1c-481e-986c-18a5d885943b','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','You have an organization dimension DimOrganizations and four related tables. Complete the modeling statements.','Connecting dimension tables across multiple levels defines a Snowflake schema. DimOrgSubVertical acts as the intermediate hierarchy table supporting DimOrgVertical.',1,NULL,NULL,'{"rows":["The model is organized into a:","Which table supports a hierarchy model for DimOrgVertical:"],"correct_mapping":{"0":"snowflake schema","1":"DimOrgSubVertical"}}',1788452722549);
INSERT INTO Question VALUES('946cf180-2ac2-4699-a001-1e4ee7fdacdb','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','You have an Opportunity table containing Qualification (0 to 1). You need to build a measure scoring opportunities as ''Low'', ''Medium'', or ''High''. How should you complete the DAX formula?','Nested IF/IF.EAGER conditions evaluate the numeric score thresholds to output text labels ''HIGH'', ''MEDIUM'', or ''LOW''.',1,NULL,NULL,'{"rows":["Condition 1 Function:","Output 1 Label:","Output 2 Label:"],"correct_mapping":{"0":"IF.EAGER","1":"\"HIGH\"","2":"\"MEDIUM\""}}',1788452722549);
INSERT INTO Question VALUES('8990a119-1cd6-401b-884a-f00a3b661cff','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You have a Power BI model connected to a frequently updated streaming data source. You need real-time analytics, minimal performance impact on source, and display of recent data without performing data refreshes. Which connectivity mode should you use?','DirectQuery mode sends queries directly to the source upon visual rendering without storing imported cached data.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('20996529-756c-427f-858b-d54c7e4732ca','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','You need to write a DAX query to rank items by Quantity without skipping rank numbers when ties occur, and return blank if an item is unfiltered. Complete the DAX formula.','HASONEVALUE checks for a single item context. Specifying DENSE ranking prevents rank gaps when identical quantities occur.',1,NULL,NULL,'{"rows":["Single Value Check Function:","Rank Method Parameter:"],"correct_mapping":{"0":"HASONEVALUE","1":"DENSE"}}',1788452722549);
INSERT INTO Question VALUES('aeced29e-c891-4114-b745-70457033b842','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You are building a Power Query M query connecting to SharePoint Online list. You need to load data, expand ''Location'', and remove ''CountryOrRegion''. Complete the M query.','Table.ExpandTableColumn expands nested records/tables, while Table.RemoveColumns drops unneeded fields from output queries.',1,NULL,NULL,'{"rows":["Expand Function:","Remove Columns Function:"],"correct_mapping":{"0":"Table.ExpandTableColumn","1":"Table.RemoveColumns"}}',1788452722549);
INSERT INTO Question VALUES('26d3dcce-0fcc-49ac-a58d-866632207f42','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','You have two related tables in Power BI Desktop with multiple relationships between them. How should you manage cross-filtering and active relationships?','Power BI allows only a single active relationship between two tables at one time, with cross-filtering configured to Single or Both direction.',1,NULL,NULL,'{"rows":["Relationship state for the second relationship:","Action required before making an inactive relationship active:"],"correct_mapping":{"0":"Single","1":"Delete the many to one."}}',1788452722549);
INSERT INTO Question VALUES('904d143a-1491-436e-b687-449b9ae3449d','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','multi_choice','Which two metrics display execution duration in Power BI Performance Analyzer? Each correct answer presents part of the solution.','Performance Analyzer logs execution time spent on DAX query evaluation and Visual display rendering.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('42b14405-e99f-4020-8344-e76f55a54629','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','single_choice','You create a dashboard using RLS filters and define a role named Consultants. To which Microsoft Entra resource can you assign the Consultants role?','RLS roles accept Entra ID Security Groups (Group2), whereas Microsoft 365 Groups are not supported for RLS assignment.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('c86f3652-fd08-432e-8dfa-9edff47143d1','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','single_choice','You need to create a DAX measure for a rolling 31-day sales total returning the total sales amount for a selected date and the previous 30 days. Which DAX expression should you use?','DATESBETWEEN calculates over a continuous date range starting at MAX(Date)-30 through MAX(Date).',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('9635abcc-161c-451d-8746-68c47ec61788','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','single_choice','You publish a semantic model containing data from Source1 (OneDrive file), Source2 (Azure SQL on VNet), and Source3 (Public website). Which data source requires an on-premises data gateway?','Azure SQL database deployed inside a Virtual Network (VNet) is isolated from public traffic, requiring a gateway connection.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('739ecec2-9d82-402a-8bc8-73ecefc5c83b','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','matrix','ReportA experiences performance issues due to model size. OrderTitle and OrderDescription are text fields not used in ReportA. How should you optimize ModelA?','Changing numerical ID fields stored as text to Whole Number improves compression. Deleting unused long text columns directly shrinks model memory footprint.',1,NULL,NULL,'{"rows":["Action for numerical ID columns stored as text:","Action for OrderTitle and OrderDescription:"],"correct_mapping":{"0":"Change data type to Whole Number","1":"Delete the OrderTitle and OrderDescription columns."}}',1788452722549);
INSERT INTO Question VALUES('e3a5df44-5b5b-4b1c-8408-9de0fae11785','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','multi_choice','You plan to use Power Query to reduce data loaded into a model with performance issues. Which two actions should you perform? Each correct answer presents part of the solution.','Group By/summarizing pre-aggregates rows, and removing unneeded columns and rows directly reduces memory consumption.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('ac0bd9d0-63c5-459e-be23-864688873e88','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You need to reduce data sent through an on-premises data gateway for Import models. Solution: Create aggregations to summarize results. Does this meet the goal?','Aggregation tables created in Power BI evaluate imported data after transfer, failing to reduce data transferred across gateway connections.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('02c92915-cf97-4486-a273-618b470b088e','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You need to reduce data sent through an on-premises data gateway for Import models. Solution: Increase Automatic page refresh intervals. Does this meet the goal?','Automatic page refresh applies exclusively to DirectQuery mode and does not alter data import transfer payloads.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('1c7dbb64-e5de-4d6e-a7d6-3b11468242d6','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','single_choice','You need to reduce data sent through an on-premises data gateway for Import models. Solution: Configure incremental refresh. Does this meet the goal?','Incremental refresh transfers only newly updated data partitions across the gateway rather than reloading entire historic datasets.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('c8c94832-8ced-400a-92d9-c38cee811cde','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You need to reduce data sent through an on-premises data gateway for Import models. Solution: Decrease dashboard cache update frequency. Does this meet the goal?','Dashboard cache update frequency controls visual rendering cache intervals in Service, not dataset refresh transfer payloads.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('efaaf016-8b6f-4414-9ead-78920e628c74','af46d95d-2638-4af3-9049-b93409487353',NULL,'DAX','matrix','You need to create a measure that displays sales for ''blue'' units while maintaining existing filter context. Complete the DAX expression.','CALCULATE evaluates the measure under modified filter context, and KEEPFILTERS preserves existing visual filter context without overriding.',1,NULL,NULL,'{"rows":["Function 1:","Function 2:"],"correct_mapping":{"0":"CALCULATE","1":"KEEPFILTERS"}}',1788452722549);
INSERT INTO Question VALUES('52226f21-d7da-4d41-9ccd-4a0697523658','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','single_choice','You need to reduce the size of an Import model without increasing report query response times. What should you do?','Removing unneeded columns directly reduces model size while leaving visual query execution speeds unimpaired.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('ce23ad43-9bd7-4fa8-a851-61e565d25864','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Modeling','multi_choice','You need to reduce the size of an Import model. Which two actions should you perform? Each correct answer presents a complete solution.','Summarizing detail data reduces row count, and optimizing column data types maximizes VertiPaq engine compression.',1,NULL,NULL,NULL,1788452722549);
INSERT INTO Question VALUES('be07aaef-379e-4405-b69e-dd016843ece2','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','drag_drop','You have a Microsoft Excel spreadsheet with Department, Stage, and School columns (School1, School2, School3, School4) containing scores. You need to prepare the data to format it with columns Department, Stage, School, and Score. Which three actions should you perform in sequence in Power Query Editor?','Unpivoting the school columns converts wide score matrix layouts into narrow attribute-value rows. Renaming Attribute to School and Value to Score assigns proper column labels. Grouping consolidates scores per department and school.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"Select the [Department] and [Stage] columns and unpivot the other columns.","1":"Rename the [Attribute] column as [School] and the [Value] column as [Score].","2":"Group by [Department] and [School]."}}',1788452792289);
INSERT INTO Question VALUES('fc3e33f9-723e-43bf-a6b4-5bd468492afa','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You have a report containing a bar chart showing customer count by customer segment and a column chart showing sales by month. You need to ensure that when a segment is selected in the bar chart, you see which portion of total sales for the month belongs to that segment. How should visual interactions be set on the column chart?','Highlighting retains the total bar height while highlighting the proportional subset representing the selected segment. Filtering would remove the rest of the total monthly context.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('4b41906e-f67f-499f-b7a6-1eaa9992282c','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','multi_choice','A user creates ReportA with a custom theme. You create DashboardA and need to ensure it uses the custom theme with minimal development effort. Which two actions should you perform? Each correct answer presents part of the solution.','Saving the theme from ReportA exports its JSON styling definition. Uploading that JSON file directly to DashboardA applies the matching theme settings.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('ce2dcab0-62d3-479e-970b-2f9f1d57f2aa','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You need to create a visualization that compares revenue and cost over time. Which type of visualization should you use?','Line charts effectively display multiple metric series (revenue and cost) across continuous time axes.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('e9386b5f-a98d-4919-8efa-3f58fdaf21c2','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','matrix','You add a key influencers visual to a Power BI report page. Complete the statements based on configuring key influencer features.','Adding fields to ''Explain By'' expands the variable factors evaluated by the model. Analyzing the ratio output indicates how many times higher a influencer impact factor evaluates.',1,NULL,NULL,'{"rows":["Increase analyzed variables by:","Factor multiplier impact value:"],"correct_mapping":{"0":"adding more fields to Explain By","1":"3"}}',1788452792289);
INSERT INTO Question VALUES('a987cc54-4b65-4d40-84f0-43eed153f4ac','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You build a report to help the sales team identify which factors affect success using a single visualization. Which type of visualization should you use?','The Key Influencers visual automatically analyzes parameters to rank and present variables driving targeted outcome metrics.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('0b642c98-9c1b-4f20-8749-1ecf577223f1','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','matrix','You have a table containing City, Total Sales, and Occupation. You need to configure a Key Influencers visual. How should you assign the fields?','The metric being evaluated (Total Sales) goes into ''Analyze'', while explanatory categorical drivers (Occupation) belong in ''Explain By''.',1,NULL,NULL,'{"rows":["Analyze field:","Explain By field:"],"correct_mapping":{"0":"Total Sales","1":"Occupation"}}',1788452792289);
INSERT INTO Question VALUES('8c41a98e-94a7-4858-b482-645700bd0c86','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You use Key Influencers visual to identify factors affecting item quantities sold in an order. What insight can be drawn when the output displays ''Customer Country is Austria | x18.8''?','Key influencers displays unit differences; a factor of 18.8 for Austria indicates customers there order 18.8 units more than average order quantities.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('78ee2a7e-d03d-4816-a888-534a3a885d00','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','multi_choice','A report has four pages with slicers for the same fields. Users report selections do not persist across pages. Which two recommendations achieve this goal? Each correct answer presents a complete solution.','Syncing slicers retains user filtering context across pages. Report-level filters inherently filter all pages across the report.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('2b052c59-3056-460e-9428-8f51eba3a829','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You need to apply conditional formatting to a Card visual: values >= 100 display dark red text, values < 100 display dark gray text. Which type of format should you use?','Rule-based conditional formatting allows setting strict numerical thresholds (e.g., >=100 or <100) to apply explicit text colors.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('86489f7a-3595-4684-8c52-2523351cefda','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','drag_drop','You have DashboardA containing TileA from ReportA. You need to provide users with additional tiles related to TileA content. Which three actions should you perform in sequence?','Selecting View Insights from tile options triggers automated data insights, focusing into generated visuals allows inspection, and pinning places selected insight tiles directly on the dashboard.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"From DashboardA, select the TileA options, and then select View Insights","1":"From Focus mode, review the generated visuals","2":"From Focus mode, pin the relevant visuals to DashboardA"}}',1788452792289);
INSERT INTO Question VALUES('1e374b89-064b-42c1-9156-49cd79c76d53','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','single_choice','You have a report page with three charts. You need to add all three charts to a dashboard while preserving interactive cross-filtering behavior between them. What should you do?','Pinning an entire report page as a live tile preserves report-level visual cross-filtering and interactivity directly on the dashboard canvas.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('32cedd29-86b5-4eae-a1bd-c0a12c621f18','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','matrix','You need to configure conditional formatting on a matrix/table where indicator color for Total Sales is driven by % Growth to Last Year based on existing calculations.','Background or font color formatting applied via Rules allows evaluating secondary measure thresholds (% Growth) to format cell values.',1,NULL,NULL,'{"rows":["Formatting element:","Format method:"],"correct_mapping":{"0":"Background color","1":"Rules"}}',1788452792289);
INSERT INTO Question VALUES('e4779812-0950-4545-a41c-7a67e7c4cf03','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','drag_drop','Build a dashboard optimized for mobile portrait view using existing report elements. Which four actions should you perform in sequence?','Pin visual elements from reports, open the dashboard canvas, switch to mobile layout editing mode, and rearrange/resize tiles for phone screens.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3","Step 4"],"correct_mapping":{"0":"Pin items from the reports to the dashboard","1":"Open the dashboard.","2":"Edit the dashboard mobile view","3":"Rearrange, resize, or remove items from the mobile layout"}}',1788452792289);
INSERT INTO Question VALUES('104f4624-1801-4138-9538-52c8b5bcc831','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','How should you create a dashed horizontal reference line denoting the 40th percentile of daily sales on a column chart visual?','Using the Analytics pane in Power BI Desktop allows adding dynamic Percentile lines calculated automatically across specified measures.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('f3e3499e-942c-4bf9-9acf-6fb4f9cb5b7c','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','multi_choice','You are building a report viewed on mobile devices and need to configure it to display data based on each user''s location. Which two actions should you perform? Each correct answer presents part of the solution.','Setting geographic Data Categories enables location-based filtering, and using those categorized fields in map visuals aligns with GPS filtering on mobile devices.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('ac01b1e4-347e-4067-89e0-a5182e1bfff9','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You have a donut chart and column chart using default visual interactions. You need to ensure selecting a bar in the column chart completely filters and redraws the donut chart. What should you do?','Selecting the source visual (column chart) and changing the target visual (donut chart) interaction control icon from Highlight to Filter forces redrawing with filtered subset data.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('0091b7b2-a444-48e0-b44b-99efd74a5ce0','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','matrix','Evaluate visual interaction icons configured between a slicer, a map visual, and a line chart visual. Complete the behavior statements.','Setting visual interaction to None ensures slicer actions do not affect the target visual. Maps and line charts support cross-filtering rather than cross-highlighting.',1,NULL,NULL,'{"rows":["Slicer selection impact when interaction set to None:","Interaction supported for Map visual:"],"correct_mapping":{"0":"not affect","1":"cross-filter"}}',1788452792289);
INSERT INTO Question VALUES('2e1abd36-d47f-4040-a3aa-e2e86f2dc97b','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You need to include a visual that automatically generates textual trend summaries and updates dynamically based on selections in other report visuals. Which visual should you use?','The Smart Narrative visual automatically generates dynamic text summaries highlighting key trends and updates as filters change.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('f1d8b4e3-9178-4d50-a4d7-a36f82f6e7fe','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You have a table visual containing a field with web image links. You need to configure the table to render the actual images instead of text URLs. What should you do?','Setting the Data Category property of the image URL column to ''Image URL'' instructs Power BI to render online images inside table cells.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('79c24072-9bde-40f6-9ccf-4dc128c571e8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Asset Management','drag_drop','You have an Excel spreadsheet named Excel1 and a dashboard named DashboardA with Q&A enabled. You need users to ask Q&A questions and pin resultant visuals while minimizing development time. Which three actions should you perform in sequence?','Format raw Excel data as a table, import Excel1 directly as a dataset in Power BI service, and add the dataset to DashboardA to enable Q&A querying.',1,NULL,NULL,'{"dropZones":["Step 1","Step 2","Step 3"],"correct_mapping":{"0":"Format the data as a table.","1":"From powerbi.com, import Excel1 as a dataset.","2":"From powerbi.com, add a tile for Excel1 dataset to DashboardA."}}',1788452792289);
INSERT INTO Question VALUES('e4d2acca-2195-4302-8759-b574c87451a8','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You have a clustered bar chart of Salary by Employee. You need a reference line showing employees above median salary. Solution: You create a constant line set to 0.5. Does this meet the goal?','A constant line set to 0.5 draws a fixed axis value at $0.50, which does not calculate the statistical median salary.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('4a20fe15-b07a-4e17-8f43-78167c2412c9','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You have a clustered bar chart of Salary by Employee. You need a reference line showing employees above median salary. Solution: You create an average line by using the Salary measure. Does this meet the goal?','The average (mean) is mathematically distinct from the median (50th percentile).',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('8d408d8b-1f31-465f-a532-57b9aeadc51d','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','single_choice','You have a clustered bar chart of Salary by Employee. You need a reference line showing employees above median salary. Solution: You create a percentile line using Salary measure set to 50%. Does this meet the goal?','The 50th percentile corresponds exactly to the statistical median of a data distribution.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('1fdc1015-e334-42ed-bd7e-dadf7b70086c','af46d95d-2638-4af3-9049-b93409487353',NULL,'Visuals & Reports','multi_choice','You are creating a Power BI dashboard containing visuals from two reports with distinct color palettes. You need a consistent dark dashboard theme while preserving original visual colors. Which two actions should you perform? Each correct answer presents part of the solution.','Selecting the dark dashboard theme updates the dashboard background styling. Choosing ''Use destination theme'' when pinning visuals applies dashboard container styling while preserving underlying visual palette selections.',1,NULL,NULL,NULL,1788452792289);
INSERT INTO Question VALUES('36c30459-41ab-49fd-bc1b-14d433367973','af46d95d-2638-4af3-9049-b93409487353',NULL,'Data Preparation','matrix','You are profiling data by using Power Query Editor. You have a table that contains a column named column1. Column statistics and Value distribution show 20 unique values, and ''Elm, American'' appears below ''Pear, flowering''. Complete the statements based on the profiling metrics.','Unique values represent non-null values that occur exactly once in the dataset (20). Sorting or positioning distributions in Power Query profile view lists items in sequential or value-rank order based on distinct value metrics.',1,NULL,NULL,'{"rows":["Unique value count statement:","Positioning evaluation statement:"],"correct_mapping":{"0":"are 20 values that occur","1":"Elm, American"}}',1788452832562);
